using System.Reflection;using NUnit.Framework;using UnityEngine;using Rootborn.Game.Common;using Rootborn.UI.Objectives;
namespace Rootborn.Tests.EditMode.UI.Objectives{public sealed class TrackedObjectiveModalVisibilityTests{
[Test]public void ModalHidesDecorationWithoutLosingTrackedObjective(){var go=new GameObject("ModalHudFixture",typeof(RectTransform));var owner=new GameObject("ModalOwner");try{var hud=go.AddComponent<TrackedObjectiveHud>();hud.Show(new ObjectiveJournalItem("item","Quests","Tracked","","Active","1/2","Next",false,0));UiGameplayInputLock.Acquire(owner);typeof(TrackedObjectiveHud).GetMethod("LateUpdate",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(hud,null);var group=go.transform.Find("TrackedObjectiveHudRoot").GetComponent<CanvasGroup>();Assert.That(group,Is.Not.Null);Assert.That(group.alpha,Is.Zero);Assert.That(hud.IsVisible,Is.True);StringAssert.Contains("Tracked",hud.VisibleText);UiGameplayInputLock.Release(owner);typeof(TrackedObjectiveHud).GetMethod("LateUpdate",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(hud,null);Assert.That(group.alpha,Is.EqualTo(1));}finally{UiGameplayInputLock.Release(owner);Object.DestroyImmediate(owner);Object.DestroyImmediate(go);}}
[Test]public void HiddenTrackingStaysHiddenAfterModalCloses(){var go=new GameObject("HiddenHudFixture",typeof(RectTransform));var owner=new GameObject("ModalOwner");try{var hud=go.AddComponent<TrackedObjectiveHud>();hud.Show(new ObjectiveJournalItem("item","Quests","Tracked","","Active","1/2","Next",false,0));UiGameplayInputLock.Acquire(owner);hud.Hide();UiGameplayInputLock.Release(owner);typeof(TrackedObjectiveHud).GetMethod("LateUpdate",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(hud,null);Assert.That(hud.IsVisible,Is.False);Assert.That(go.transform.Find("TrackedObjectiveHudRoot").gameObject.activeSelf,Is.False);}finally{UiGameplayInputLock.Release(owner);Object.DestroyImmediate(owner);Object.DestroyImmediate(go);}}
}}

